e indicadores (badges): Uso del rojo institucional para resaltar conteos y notificaciones */\r\n.badge-secondary,\r\n.tabs .badge,\r\n.liste_titre .badge:not(.nochangebackground) {\r\n  background-color: #dc3545;\r\n  color: #fff !important;\r\n}\r\n\r\n/* Identidad visual en títulos: Aplicación del azul obscuro corporativo a referencias y encabezados de página */\r\n.refid,\r\n.titre {\r\n  color: #152c5b;\r\n}\r\n/* Botonrs buscar */\r\n/*.infobox-adherent,*/\r\n/*.infobox-member,*/\r\n/*.infobox-expensereport,*/\r\n.pictofixedwidth,\r\n.button_search,\r\n.button_removefilter {\r\n  border: unset;\r\n  background-color: unset !important;\r\n  color: #fff !important;\r\n}\r\n\r\n/* Badge Info*/\r\n.badge-info {\r\n  color: #fff;\r\n  background-color: #17a2b8;\r\n}\r\n/* Badge Warning */\r\n.badge-warning {\r\n  color: #1f2d3d !important;\r\n  background-color: #ffc107;\r\n}\r\n\r\n/* Badge Susscess */\r\n.badge-status4 {\r\n  color: #ffffff !important;\r\n  background-color: #28a745 !important;\r\n}\r\n\r\n/* Badge warning */\r\n.badge-status1, .badge-status2 {\r\n  background-color: #ffc107 !important;\r\n  color: #1f2d3d !important;\r\n}\r\n\r\n/* Badges stadistics db */\r\n.boxstats, \r\n.boxstats130 {\r\n    border-left: 6px solid #152c5b !important;\r\n}\r\n\r\n/* Warnings icons */\r\n.pictowarning {\r\n    /* vertical-align: text-bottom; */\r\n    color: #ffc107 !important;\r\n}\r\n\r\n/* RECURRENCE FIELD*/\r\n.fichecenter .tableforfield:not(.margintable) tr td, \r\n.tagtr.table-border-row {\r\n    background-color: var(--colorbacklineimpair3);\r\n}\r\n/**/\r\n.pictofixedwidth{\r\n    color: #152c5b !important;\r\n}\r\n\r\n.font-status4, .font-status8  {\r\n    color: #6377a0 !important;\r\n}\r\n\r\n.a-filter-disabled, .a-mesure-disabled {\r\n    color: #ffffff !important;\r\n}','chaine',0,'','2026-05-09 06:16:19'),(440,'MAIN_IHM_PARAMS_REV',1,'26','chaine',0,'','2026-05-09 06:16:19'),(441,'MAIN_SESSION_TIMEOUT',1,'1440','chaine',0,'','2026-05-09 06:17:42'),